(let [cols ["ip_country" "eur_amount" "has_fraudulent_dispute"] res (loop [cur nil acc {}] (let [p (dabstep.payments/read-page cur cols) a (reduce (fn [m row] (let [c (nth row 0) amt (nth row 1) f (nth row 2) old (get m c [0 0]) t (+ (nth old 0) (or amt 0)) v (+ (nth old 1) (if f (or amt 0) 0))] (assoc m c [t v]))) acc (get p :rows))] (if (nil? (get p :next_cursor)) a (recur (get p :next_cursor) a)))) opts [["A" "NL"] ["B" "BE"] ["C" "ES"] ["D" "FR"]] scored (map (fn [[l c]] (let [[t v] (get res c [0 0])] [l c (if (pos? t) (/ v t) 0) t v])) opts) best (reduce (fn [x y] (if (> (nth y 2) (nth x 2)) y x)) (first scored) (rest scored))] (return (str (nth best 0) ". " (nth best 1))))
